'use strict';
const KEY='msp-protocole-v1';
const WORD_LOGO='data:image/png;base64,';
const groups={
identityFields:[['title','Titre du protocole *','text','Ex. : Coordination du suivi du diabète de type 2'],['theme','Thématique / situation de soins *','text','Pathologie ou point critique du parcours'],['msp','Nom de la MSP *'],['town','Commune / territoire'],['owner','Référent du protocole *'],['version','Version','text','Ex. : 1.0'],['created','Date de rédaction','date'],['review','Date de révision prévue *','date']],
teamFields:[['team','Professions et membres impliqués *','textarea','Une ligne par profession, avec les membres ou fonctions concernés.'],['need','Besoin identifié et pratiques actuelles *','textarea','Quel problème partagé souhaitez-vous résoudre ?'],['goal','Objectif de la prise en charge *','textarea','Quel changement concret attendez-vous pour les patients ?'],['population','Population concernée et critères d’inclusion *','textarea','Définir à qui le protocole s’adresse.'],['exclusion','Critères d’exclusion et situations hors protocole *','textarea','Préciser les limites du parcours.']],
qualityFields:[['references','Recommandations et documents de référence *','textarea','Organisme, titre, date/version et lien. L’équipe doit vérifier leur actualité.'],['validation','Modalités de validation collective *','textarea','Participants, réunion, relecture, accord des professions concernées.'],['validated','Date de validation par l’équipe','date'],['validators','Professionnels ayant validé le protocole','textarea','À compléter après validation effective.'],['distribution','Diffusion et accès au protocole *','textarea','Où l’équipe retrouve-t-elle la version en vigueur ?'],['cpam','Échanges avec la CPAM','textarea','Co-construction, avis et pièces à transmettre, selon les modalités de votre caisse.']],
pathFields:[['place','Lieux de prise en charge *','textarea','MSP, domicile, officine, partenaires…'],['coordination','Partage d’informations entre professionnels *','textarea','Outil, destinataires, contenu utile et moment de transmission.'],['patient','Information et participation du patient *','textarea','Modalités d’information, accord et prise en compte des préférences.'],['risks','Alertes, exceptions et conduite à tenir *','textarea','Signes d’alerte, responsable à contacter et délais, selon les références retenues.']],
evaluationFields:[['indicators','Indicateurs d’évaluation *','textarea','Pour chacun : numérateur / dénominateur ou mesure, cible, source, fréquence, responsable.'],['feedback','Retours d’expérience et réactualisation *','textarea','Qui analyse les écarts et événements indésirables ? Quand réviser le protocole ?'],['resources','Moyens nécessaires','textarea','Temps, outils, formation, partenaires et ressources.']]
};
const columns=[['who','Qui *','Profession responsable et partenaires'],['what','Quoi *','Action à réaliser'],['where','Où','Lieu ou contexte'],['when','Quand *','Déclencheur, délai ou fréquence'],['why','Pourquoi','Objectif de l’étape'],['how','Comment *','Modalités, outil, transmission, trace et référence']];
const definitions=Object.values(groups).flat();
let state={fields:{},rows:[emptyRow()]};let step=0;let storageAvailable=true;
function emptyRow(){return {who:'',what:'',where:'',when:'',why:'',how:''};}
function escapeHTML(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function safeDraft(data){if(!data||data.schema!==1||!data.fields||typeof data.fields!=='object'||!Array.isArray(data.rows)||!data.rows.length||data.rows.length>50)throw Error('Format de brouillon invalide.');const fields={};for(const [key] of definitions){const v=data.fields[key];if(v!==undefined&&typeof v!=='string')throw Error('Valeur de champ invalide.');fields[key]=(v||'').slice(0,20000);}return {fields,rows:data.rows.map(r=>{if(!r||typeof r!=='object')throw Error('Étape invalide.');return Object.fromEntries(columns.map(([key])=>{if(r[key]!==undefined&&typeof r[key]!=='string')throw Error('Valeur d’étape invalide.');return [key,(r[key]||'').slice(0,20000)];}));})};}
try{const data=localStorage.getItem(KEY);if(data)state=safeDraft(JSON.parse(data));}catch(e){storageAvailable=false;}
function fieldHTML([id,label,type='text',help='']){const full=type==='textarea';return `<div class="field ${full?'full':''}"><label for="${id}">${label}</label>${full?`<textarea id="${id}" name="${id}" aria-describedby="help-${id}">${escapeHTML(state.fields[id])}</textarea>`:`<input id="${id}" name="${id}" type="${type}" value="${escapeHTML(state.fields[id])}" aria-describedby="help-${id}">`}<p class="help" id="help-${id}">${help}</p></div>`;}
function renderFields(){for(const [id,defs] of Object.entries(groups))document.getElementById(id).innerHTML=defs.map(fieldHTML).join('');}
function renderRows(){document.getElementById('rows').innerHTML=state.rows.map((r,i)=>`<section class="row-card"><div class="row-head"><h3>Étape ${i+1}</h3><button type="button" data-remove="${i}" ${state.rows.length===1?'disabled':''}>Supprimer l’étape ${i+1}</button></div><div class="fields">${columns.map(([key,label,help])=>`<div class="field"><label for="row-${i}-${key}">${label}</label><textarea id="row-${i}-${key}" data-row="${i}" data-key="${key}" aria-describedby="rh-${i}-${key}">${escapeHTML(r[key])}</textarea><p class="help" id="rh-${i}-${key}">${help}</p></div>`).join('')}</div></section>`).join('');}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({schema:1,...state}));storageAvailable=true;}catch(e){storageAvailable=false;}document.getElementById('saveState').textContent=storageAvailable?'Enregistré dans ce navigateur':'Sauvegarde locale indisponible · exportez';update();}
function present(v){return typeof v==='string'&&v.trim().length>0;}
function readiness(){return definitions.filter(d=>d[1].includes('*')).map(([key,label])=>({label:label.replace(' *',''),ok:present(state.fields[key])})).concat(state.rows.map((r,i)=>({label:`Étape ${i+1} : qui, quoi, quand, comment`,ok:['who','what','when','how'].every(k=>present(r[k]))})));}
function checks(){return [{label:'Identité et besoin définis',ok:['title','theme','msp','owner','need','goal','population','exclusion'].every(k=>present(state.fields[k]))},{label:'Équipe et références renseignées',ok:['team','references'].every(k=>present(state.fields[k]))},{label:'Parcours et coordination décrits',ok:['place','coordination','patient','risks'].every(k=>present(state.fields[k]))&&state.rows.every(r=>['who','what','when','how'].every(k=>present(r[k])))},{label:'Évaluation et révision prévues',ok:['indicators','feedback','review','distribution','validation'].every(k=>present(state.fields[k]))},{label:'Validation collective documentée',ok:['validated','validators'].every(k=>present(state.fields[k]))}];}
function update(){const list=readiness();const count=list.filter(x=>x.ok).length;document.getElementById('meterFill').style.width=`${count/list.length*100}%`;document.getElementById('progressText').textContent=`${count} / ${list.length} éléments renseignés pour la relecture`;document.getElementById('checklist').innerHTML=checks().map(c=>`<li class="${c.ok?'done':''}">${c.label}</li>`).join('');renderDocument();}
function value(key,fallback='À compléter par l’équipe'){const v=state.fields[key];return present(v)?escapeHTML(v):`<span class="missing">${fallback}</span>`;}
function date(key){const v=state.fields[key];if(!present(v))return value(key);const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(v);return m?`${m[3]}/${m[2]}/${m[1]}`:escapeHTML(v);}
function textSection(title,key){return `<h3>${title}</h3><p class="doc-text">${value(key)}</p>`;}
function renderDocument(){const missing=readiness().filter(x=>!x.ok);const signed=present(state.fields.validated)&&present(state.fields.validators);document.getElementById('warnings').innerHTML=missing.length?`<div class="alert"><strong>Trame incomplète : ${missing.length} élément(s) à renseigner</strong><ul>${missing.map(c=>`<li>${escapeHTML(c.label)}</li>`).join('')}</ul></div>`:`<div class="note">Les informations de rédaction sont renseignées. ${signed?'La validation déclarée reste sous la responsabilité de l’équipe.':'Document à soumettre à la validation collective.'} L’éligibilité ACI n’est pas vérifiée automatiquement.</div>`;
const meta=[['MSP','msp'],['Territoire','town'],['Thématique','theme'],['Référent','owner'],['Version','version'],['Date de rédaction','created'],['Validation déclarée','validated'],['Révision prévue','review']];
document.getElementById('document').innerHTML=`<div class="document-brand"><img src="femas-hdf.png" alt="FEMAS Hauts-de-France" width="145" height="40"><span>Formulaire FEMAS HDF · Protocoles MSP</span></div><p class="eyebrow">PROTOCOLE PLURIPROFESSIONNEL · MSP</p><h1>${value('title','Titre du protocole à renseigner')}</h1><p class="doc-meta">${signed?'Validation déclarée par l’équipe':'Brouillon · à valider par l’équipe'} · Tableau QQOQPC</p><h2>Fiche d’identité</h2><div class="doc-grid">${meta.map(([label,key])=>`<div class="doc-item"><strong>${label}</strong>${['created','validated','review'].includes(key)?date(key):value(key)}</div>`).join('')}</div>${textSection('Équipe impliquée','team')}${textSection('Besoin et pratiques actuelles','need')}${textSection('Objectif','goal')}${textSection('Population et critères d’inclusion','population')}${textSection('Critères d’exclusion','exclusion')}${textSection('Recommandations et références retenues','references')}<h2>Protocole · Tableau QQOQPC</h2><p>Qui · Quoi · Où · Quand · Pourquoi · Comment</p><div class="table-wrap"><table><thead><tr><th scope="col">Étape</th>${columns.map(([,label])=>`<th scope="col">${label.replace(' *','')}</th>`).join('')}</tr></thead><tbody>${state.rows.map((r,i)=>`<tr><td>${i+1}</td>${columns.map(([key])=>{let v=r[key];if(!present(v)&&key==='where')v=state.fields.place;if(!present(v)&&key==='why')v=state.fields.goal;return `<td>${present(v)?escapeHTML(v):'<span class="missing">À compléter</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${textSection('Coordination et partage d’informations','coordination')}${textSection('Information et participation du patient','patient')}${textSection('Alertes, exceptions et conduite à tenir','risks')}${textSection('Moyens nécessaires','resources')}<h2>Évaluation, validation et actualisation</h2>${textSection('Indicateurs et modalités de mesure','indicators')}${textSection('Retours d’expérience et réactualisation','feedback')}${textSection('Modalités de validation collective','validation')}${textSection('Professionnels ayant validé le protocole','validators')}${textSection('Diffusion et accès à la version en vigueur','distribution')}${textSection('Échanges avec la CPAM','cpam')}<div class="note">Document généré à partir des déclarations de l’équipe. Références cliniques et organisation à vérifier collectivement avant utilisation. Cette trame ne vaut ni validation clinique ni accord de valorisation ACI. Chaque intervenant agit dans son champ de compétences.</div><p class="small">Cadre méthodologique : HAS, « Comment élaborer et mettre en œuvre des protocoles pluriprofessionnels ? » (2015). Cadre conventionnel : ACI, avenant n° 2 approuvé par arrêté du 8 juillet 2026. Sources consultées le 6 octobre 2026.</p>`;}
function go(n){step=n;const titles=["Construisez votre protocole","Organisez votre parcours","Votre protocole pluriprofessionnel"];const descriptions=["Présentez votre MSP, décrivez votre parcours, obtenez votre protocole pluriprofessionnel.","Précisez le rôle de chacun, les moments d’intervention et les échanges entre professionnels.","Relisez votre fiche et le tableau QQOQPC avec l’équipe, puis exportez votre document."];document.getElementById("heroNumber").textContent=n+1;document.getElementById("heroTitle").textContent=titles[n];document.getElementById("heroDescription").textContent=descriptions[n];document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=Number(p.dataset.panel)!==n);document.querySelector('.workspace').hidden=n===2;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.step)===n);b.setAttribute('aria-current',Number(b.dataset.step)===n?'step':'false');});update();window.scrollTo({top:0,behavior:"instant"});}
document.getElementById('form').addEventListener('submit',e=>e.preventDefault());
document.getElementById('form').addEventListener('input',e=>{const el=e.target;if(el.dataset.row!==undefined)state.rows[Number(el.dataset.row)][el.dataset.key]=el.value;else if(el.name)state.fields[el.name]=el.value;persist();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined)go(Number(b.dataset.step));if(b.dataset.next!==undefined)go(Number(b.dataset.next));if(b.dataset.remove!==undefined&&state.rows.length>1){state.rows.splice(Number(b.dataset.remove),1);renderRows();persist();}});
document.getElementById('addRow').onclick=()=>{if(state.rows.length>=50){message('50 étapes maximum.');return;}state.rows.push(emptyRow());renderRows();persist();document.getElementById(`row-${state.rows.length-1}-who`).focus();};
function message(text){document.getElementById('message').textContent=text;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
document.getElementById('export').onclick=()=>{download('brouillon-protocole-msp.json',JSON.stringify({schema:1,...state},null,2),'application/json');message('Brouillon exporté. Conservez ce fichier pour reprendre votre travail.');};
document.getElementById('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Fichier trop volumineux (2 Mo maximum).');const draft=safeDraft(JSON.parse(await file.text()));if(confirm('Remplacer le brouillon actuel par le fichier importé ?')){state=draft;renderFields();renderRows();persist();message('Brouillon importé.');}}catch(err){message(`Import impossible : ${err.message}`);}finally{e.target.value='';}};
document.getElementById('reset').onclick=()=>{if(confirm('Effacer le brouillon de ce navigateur ? Exportez-le au préalable pour le conserver.')){state={fields:{},rows:[emptyRow()]};renderFields();renderRows();persist();go(0);message('Brouillon effacé.');}};
document.getElementById('print').onclick=()=>{renderDocument();window.print();};
function protocolWordHtml(){renderDocument();return `<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Protocole MSP</title><style>body{font-family:Arial;font-size:11pt}table{border-collapse:collapse;width:100%}th,td{border:1px solid #aaa;padding:8px;vertical-align:top;white-space:pre-wrap}h1{font-size:22pt}.doc-text,.doc-item{white-space:pre-wrap}.missing{color:#97500c}.doc-item{margin:8px 0}.doc-item strong{display:block}.note{border:1px solid #aaa;padding:12px}</style></head><body>${document.getElementById('document').innerHTML.replace('src="femas-hdf.png"', 'src="'+WORD_LOGO+'"')}</body></html>`;}
document.getElementById('word').onclick=()=>{download('protocole-msp.doc',protocolWordHtml(),'application/msword');message('Document HTML compatible Word téléchargé (.doc).');};
document.getElementById('example').onclick=()=>{if((Object.values(state.fields).some(present)||state.rows.some(r=>Object.values(r).some(present)))&&!confirm('Remplacer le brouillon par un exemple fictif ?'))return;state={fields:{title:'Exemple fictif · Coordination d’un suivi pluriprofessionnel',theme:'Organisation du suivi d’une maladie chronique',msp:'MSP Démonstration (fictive)',town:'Territoire fictif',owner:'Référent de coordination (exemple)',version:'0.1 · exemple',created:'2026-10-06',review:'2027-10-06',team:'Médecin généraliste : suivi médical\nInfirmier : accompagnement et suivi\nPharmacien : suivi pharmaceutique\nCoordonnateur : organisation',need:'Exemple : informations dispersées entre les professionnels et suivi insuffisamment coordonné.',goal:'Formaliser un parcours partagé et améliorer la continuité de l’information.',population:'À définir par l’équipe en fonction de la situation clinique.',exclusion:'À définir à partir des recommandations retenues.',references:'À renseigner : recommandations sanitaires actualisées relatives à la thématique choisie. Cet exemple ne fournit aucune recommandation clinique.',validation:'Relecture et validation en réunion par chaque profession impliquée ; compte rendu à conserver.',distribution:'Version en vigueur accessible dans l’espace documentaire partagé de la MSP.',place:'MSP et officine partenaire, selon l’organisation locale.',coordination:'Informations utiles tracées dans le dossier partagé selon les droits d’accès ; échanges sécurisés avec les partenaires.',patient:'Informer la personne du parcours proposé et recueillir ses préférences et son accord.',risks:'Définir les situations d’alerte et les délais d’orientation à partir des recommandations ; les faire valider par l’équipe.',indicators:'Indicateur organisationnel proposé : nombre de suivis avec synthèse partagée / nombre de suivis inclus. Cible, fréquence et responsable à définir.',feedback:'Analyse collective des écarts et des retours patients ; révision annuelle et après changement de recommandations.',resources:'Temps de concertation, espace documentaire et dossier partagé.'},rows:[{who:'Professionnel qui repère la situation',what:'Vérifier l’entrée dans le parcours et informer le patient',where:'',when:'Lors du repérage de la situation',why:'Organiser l’entrée dans le parcours',how:'Appliquer les critères validés par l’équipe et tracer l’accord et l’orientation.'},{who:'Professionnels concernés par le suivi',what:'Réaliser les interventions convenues par l’équipe',where:'',when:'Selon le calendrier défini pour la situation',why:'',how:'Préciser les interventions et références cliniques ; partager les informations utiles.'},{who:'Référent et équipe pluriprofessionnelle',what:'Évaluer le parcours et ajuster son organisation',where:'MSP',when:'À l’échéance choisie par l’équipe',why:'Améliorer la continuité du suivi',how:'Analyser les indicateurs, les écarts et les retours patients ; consigner les décisions.'}]};renderFields();renderRows();persist();message('Exemple fictif chargé. Les mentions « à définir » nécessitent une rédaction par l’équipe.');};
renderFields();renderRows();go(0);document.getElementById('saveState').textContent=storageAvailable?'Brouillon local · sauvegarde automatique':'Sauvegarde locale indisponible · exportez';
